package org.example.server.persistence.entity;
import jakarta.persistence.*;import org.example.server.util.BusinessClock;
@Entity @Table(name="purchase_recon_import_batch")
public class PurchaseReconImportBatchEntity{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(name="source_file_name") private String sourceFileName;@Column(name="source_fingerprint",unique=true) private String sourceFingerprint;@Column(name="import_note") private String importNote;@Column(name="imported_by") private String importedBy;@Column(name="imported_at") private String importedAt;@Column(name="total_rows",nullable=false) private Integer totalRows=0;@Column(name="imported_rows",nullable=false) private Integer importedRows=0;@Column(name="duplicate_rows",nullable=false) private Integer duplicateRows=0;@Column(name="warning_rows",nullable=false) private Integer warningRows=0;@Column(name="ignored_rows",nullable=false) private Integer ignoredRows=0;
 @PrePersist void create(){if(importedAt==null)importedAt=BusinessClock.nowUtcText();if(totalRows==null)totalRows=0;if(importedRows==null)importedRows=0;if(duplicateRows==null)duplicateRows=0;if(warningRows==null)warningRows=0;if(ignoredRows==null)ignoredRows=0;}
 public Long getId(){return id;}public void setId(Long v){id=v;}public String getSourceFileName(){return sourceFileName;}public void setSourceFileName(String v){sourceFileName=v;}public String getSourceFingerprint(){return sourceFingerprint;}public void setSourceFingerprint(String v){sourceFingerprint=v;}public String getImportNote(){return importNote;}public void setImportNote(String v){importNote=v;}public String getImportedBy(){return importedBy;}public void setImportedBy(String v){importedBy=v;}public String getImportedAt(){return importedAt;}public Integer getTotalRows(){return totalRows;}public void setTotalRows(Integer v){totalRows=v;}public Integer getImportedRows(){return importedRows;}public void setImportedRows(Integer v){importedRows=v;}public Integer getDuplicateRows(){return duplicateRows;}public void setDuplicateRows(Integer v){duplicateRows=v;}public Integer getWarningRows(){return warningRows;}public void setWarningRows(Integer v){warningRows=v;}public Integer getIgnoredRows(){return ignoredRows;}public void setIgnoredRows(Integer v){ignoredRows=v;}
}
